313	\begin{lemma}[Unitarity and conjugation action of the swap unitaries]\label{lem:v-swap-conjugation}
314		\lean{MIPStarRE.QPBT.swapUnitary_mul_conjTranspose}
315		\lean{MIPStarRE.QPBT.conjTranspose_mul_swapUnitary}
316		\lean{MIPStarRE.QPBT.swapUnitary_conj_tildeObs}
